@page "/settings"
@using sv_67888b997ec7444d9473993a4ceb2759.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span class="nav-label">@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast @_toastType">
                <span>@_toastMessage</span>
                <button class="toast-close" @onclick="DismissToast">&times;</button>
            </div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast state
    private bool _toastVisible;
    private string _toastMessage = "";
    private string _toastType = "success";

    // Profile state
    private UserProfile? _profile;
    private UserProfile? _savedProfile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editBio = "";
    private string _editAvatarUrl = "";

    // Notification state
    private NotificationPrefs? _notificationPrefs;

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _sessionToRevoke;
    private bool _showRevokeConfirmation;

    // Appearance state
    private AppearanceSettings? _appearanceSettings;
    private string _editTheme = "System";
    private string _editFontSize = "Medium";
    private string _editLanguage = "en";
    private bool _editCompactMode;

    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨")
    };

    private static readonly string[] _availableLanguages = { "en", "es", "fr", "de", "ja", "zh", "pt", "ko" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllDataAsync();
        _loading = false;
    }

    private async Task LoadAllDataAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        _savedProfile = _profile;
        ResetProfileFields();

        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _appearanceSettings = await SettingsService.GetAppearanceAsync();
        ResetAppearanceFields();
    }

    private void ResetProfileFields()
    {
        if (_savedProfile is null) return;
        _editDisplayName = _savedProfile.DisplayName;
        _editEmail = _savedProfile.Email;
        _editBio = _savedProfile.Bio;
        _editAvatarUrl = _savedProfile.AvatarUrl;
    }

    private void ResetAppearanceFields()
    {
        if (_appearanceSettings is null) return;
        _editTheme = _appearanceSettings.Theme;
        _editFontSize = _appearanceSettings.FontSize;
        _editLanguage = _appearanceSettings.Language;
        _editCompactMode = _appearanceSettings.CompactMode;
    }

    // --- Profile ---
    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.", "info");
    }

    // --- Notifications ---
    private void ToggleEmailNotifications(ChangeEventArgs e)
    {
        if (_notificationPrefs is null) return;
        _notificationPrefs = _notificationPrefs with { EmailNotifications = (bool)(e.Value ?? false) };
    }

    private void TogglePushNotifications(ChangeEventArgs e)
    {
        if (_notificationPrefs is null) return;
        _notificationPrefs = _notificationPrefs with { PushNotifications = (bool)(e.Value ?? false) };
    }

    private void ToggleWeeklyDigest(ChangeEventArgs e)
    {
        if (_notificationPrefs is null) return;
        _notificationPrefs = _notificationPrefs with { WeeklyDigest = (bool)(e.Value ?? false) };
    }

    private void ToggleMutedChannel(string channel, ChangeEventArgs e)
    {
        if (_notificationPrefs is null) return;
        var muted = (bool)(e.Value ?? false);
        var channels = new List<string>(_notificationPrefs.MutedChannels);
        if (muted && !channels.Contains(channel))
            channels.Add(channel);
        else if (!muted)
            channels.Remove(channel);
        _notificationPrefs = _notificationPrefs with { MutedChannels = channels };
    }

    private async Task SaveNotificationPrefs()
    {
        if (_notificationPrefs is null) return;
        await SettingsService.SaveNotificationPrefsAsync(_notificationPrefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // --- Security ---
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword != _confirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevokeSession(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirmation = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeConfirmation = false;
        _sessionToRevoke = null;
        ShowToast("Session revoked.", "success");
    }

    private void CancelRevokeSession()
    {
        _showRevokeConfirmation = false;
        _sessionToRevoke = null;
    }

    // --- Appearance ---
    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearanceSettings = updated;
        ShowToast("Appearance settings saved!", "success");
    }

    // --- Toast ---
    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _toastVisible = true;
        _ = AutoDismissToast();
    }

    private async Task AutoDismissToast()
    {
        await Task.Delay(3000);
        _toastVisible = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => _toastVisible = false;

    // --- Render fragments ---
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-preview">
                @if (!string.IsNullOrEmpty(_editAvatarUrl))
                {
                    <img src="@_editAvatarUrl" alt="Avatar" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <span class="avatar-url-display">@_editAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_editDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_editEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="_editBio" rows="4"></textarea>
            </div>

            <div class="form-group">
                <label for="avatarUrl">Avatar URL</label>
                <input id="avatarUrl" type="url" @bind="_editAvatarUrl" />
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            @if (_notificationPrefs is not null)
            {
                <div class="toggle-group">
                    <label class="toggle-item">
                        <input type="checkbox" checked="@_notificationPrefs.EmailNotifications"
                               @onchange="ToggleEmailNotifications" />
                        <span class="toggle-switch"></span>
                        <span>Email Notifications</span>
                    </label>

                    <label class="toggle-item">
                        <input type="checkbox" checked="@_notificationPrefs.PushNotifications"
                               @onchange="TogglePushNotifications" />
                        <span class="toggle-switch"></span>
                        <span>Push Notifications</span>
                    </label>

                    <label class="toggle-item">
                        <input type="checkbox" checked="@_notificationPrefs.WeeklyDigest"
                               @onchange="ToggleWeeklyDigest" />
                        <span class="toggle-switch"></span>
                        <span>Weekly Digest</span>
                    </label>
                </div>

                <h3>Muted Channels</h3>
                <div class="channel-list">
                    @if (_notificationPrefs.MutedChannels.Count == 0)
                    {
                        <p class="text-muted">No channels available.</p>
                    }
                    else
                    {
                        @foreach (var channel in _notificationPrefs.MutedChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox" checked="@true"
                                       @onchange="(e) => ToggleMutedChannel(channel, e)" />
                                <span>@channel</span>
                            </label>
                        }
                    }
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
                </div>
            }
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▼" : "▶")</span>
                </button>

                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            @if (_securitySettings is not null)
            {
                <div class="security-item">
                    <h3>Two-Factor Authentication</h3>
                    <div class="status-indicator">
                        <span class="status-dot @(_securitySettings.TwoFactorEnabled ? "enabled" : "disabled")"></span>
                        <span>@(_securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")</span>
                    </div>
                </div>

                @if (_securitySettings.LastPasswordChange.HasValue)
                {
                    <p class="text-muted">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }

                <h3>Active Sessions</h3>
                <div class="sessions-table-container">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != _securitySettings.Sessions.FirstOrDefault())
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevokeSession(session.Id)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="text-muted">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>

                @if (_showRevokeConfirmation)
                {
                    <div class="modal-overlay">
                        <div class="modal-dialog">
                            <h4>Confirm Session Revocation</h4>
                            <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                            <div class="button-group">
                                <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke Session</button>
                                <button class="btn btn-secondary" @onclick="CancelRevokeSession">Cancel</button>
                            </div>
                        </div>
                    </div>
                }
            }
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_editTheme == theme)"
                                   @onchange="() => _editTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_editFontSize == size)"
                                   @onchange="() => _editFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_editLanguage">
                    @foreach (var lang in _availableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-item">
                    <input type="checkbox" checked="@_editCompactMode"
                           @onchange="(e) => _editCompactMode = (bool)(e.Value ?? false)" />
                    <span class="toggle-switch"></span>
                    <span>Compact Mode</span>
                </label>
            </div>

            <div class="appearance-preview">
                <h4>Preview</h4>
                <div class="preview-box @(_editTheme.ToLowerInvariant()) @(_editCompactMode ? "compact" : "") font-@(_editFontSize.ToLowerInvariant())">
                    <p class="preview-heading">Sample Heading</p>
                    <p class="preview-text">This is how your content will look with the selected settings.</p>
                    <button class="preview-button">Sample Button</button>
                </div>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

