namespace sv_67888b997ec7444d9473993a4ceb2759.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--sidebar-bg, #f8f9fa);
    border-right: 1px solid var(--border-color, #dee2e6);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.85rem 1.5rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: var(--text-color, #495057);
    border-left: 3px solid transparent;
    transition: all 0.2s ease;
}

.settings-nav li:hover {
    background: var(--hover-bg, #e9ecef);
    color: var(--text-primary, #212529);
}

.settings-nav li.active {
    background: var(--active-bg, #e7f1ff);
    color: var(--primary-color, #0d6efd);
    border-left-color: var(--primary-color, #0d6efd);
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 1.5rem;
    color: var(--text-primary, #212529);
}

.settings-section h3 {
    font-size: 1.1rem;
    font-weight: 600;
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
}

/* Form Controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    font-size: 0.9rem;
    color: var(--label-color, #495057);
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.85rem;
    border: 1px solid var(--border-color, #ced4da);
    border-radius: 6px;
    font-size: 0.9rem;
    transition: border-color 0.2s;
    background: var(--input-bg, #fff);
    color: var(--text-color, #212529);
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: var(--primary-color, #0d6efd);
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.1);
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary {
    background: var(--primary-color, #0d6efd);
    color: #fff;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: var(--secondary-bg, #e9ecef);
    color: var(--text-color, #495057);
}

.btn-secondary:hover {
    background: #d3d8de;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: var(--card-bg, #f8f9fa);
    border-radius: 8px;
}

.avatar-img {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid var(--border-color, #dee2e6);
}

.avatar-placeholder {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    background: var(--secondary-bg, #e9ecef);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    color: var(--text-muted, #6c757d);
}

.avatar-url-display {
    font-size: 0.8rem;
    color: var(--text-muted, #6c757d);
    word-break: break-all;
}

/* Toggle Switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.toggle-item input[type="checkbox"] {
    width: 40px;
    height: 22px;
    appearance: none;
    background: #ccc;
    border-radius: 11px;
    position: relative;
    cursor: pointer;
    transition: background 0.3s;
    flex-shrink: 0;
}

.toggle-item input[type="checkbox"]:checked {
    background: var(--primary-color, #0d6efd);
}

.toggle-item input[type="checkbox"]::before {
    content: '';
    position: absolute;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #fff;
    top: 2px;
    left: 2px;
    transition: transform 0.3s;
}

.toggle-item input[type="checkbox"]:checked::before {
    transform: translateX(18px);
}

/* Channel List */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    font-size: 0.9rem;
    cursor: pointer;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 1.25rem;
    background: var(--card-bg, #f8f9fa);
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: var(--hover-bg, #e9ecef);
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid var(--border-color, #dee2e6);
}

/* Security Status */
.security-item {
    margin-bottom: 1rem;
}

.status-indicator {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.9rem;
}

.status-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

.status-dot.enabled {
    background: #198754;
}

.status-dot.disabled {
    background: #dc3545;
}

/* Sessions Table */
.sessions-table-container {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.875rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--border-color, #dee2e6);
}

.sessions-table th {
    font-weight: 600;
    color: var(--text-muted, #6c757d);
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 12px;
    padding: 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
}

.modal-dialog h4 {
    margin: 0 0 0.75rem;
}

.modal-dialog p {
    color: var(--text-muted, #6c757d);
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.9rem;
}

/* Appearance Preview */
.appearance-preview {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
}

.preview-box {
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 8px;
    padding: 1.5rem;
    transition: all 0.3s ease;
}

.preview-box.light {
    background: #ffffff;
    color: #212529;
}

.preview-box.dark {
    background: #1a1a2e;
    color: #e0e0e0;
}

.preview-box.system {
    background: #f0f4f8;
    color: #2d3748;
}

.preview-box.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-box.font-small {
    font-size: 0.8rem;
}

.preview-box.font-medium {
    font-size: 1rem;
}

.preview-box.font-large {
    font-size: 1.2rem;
}

.preview-heading {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-text {
    opacity: 0.8;
    margin-bottom: 0.75rem;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 4px;
    border: 1px solid currentColor;
    background: transparent;
    color: inherit;
    cursor: default;
    font-size: inherit;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    padding: 0.85rem 1.25rem;
    border-radius: 8px;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.9rem;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
    z-index: 2000;
    animation: slideIn 0.3s ease;
}

.toast.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast.error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast.info {
    background: #cff4fc;
    color: #055160;
    border: 1px solid #b6effb;
}

.toast-close {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: inherit;
    opacity: 0.7;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from {
        transform: translateX(100%);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

/* Utilities */
.text-muted {
    color: var(--text-muted, #6c757d);
    font-size: 0.85rem;
}

.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4rem;
    color: var(--text-muted, #6c757d);
    font-size: 1rem;
}

